"""Independent original-unit matrix/cone audit of actual P1 linear solve."""
import sys,json,shutil,time
import numpy as np
from scipy import sparse
from baseline_registry import ROOT,REPO,ref,dump

def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);c=np.load(REPO/s['output']['path']);x=np.r_[c['increment_mm'],c['tension_extension_mm']];y=c['physical_dual'];q=p['q'];lo=p['lower'];hi=p['upper'];D=p['D'];E=p['E'];active=p['active'];basis=p['basis'];T=p['T'];eq=np.isfinite(hi)&(lo==hi);ineq=~eq;sl=A@x-lo;g=P@x+q+A.T@y
 metrics=dict(physical_primal_mm=max(float(np.max(np.maximum(-sl,0))),float(np.max(abs(sl[eq])))),physical_dual_N=float(np.max(abs(g))),physical_sign_defect_N=float(np.max(np.maximum(y[ineq],0))),physical_complementarity_Nmm=float(np.max(abs(sl[ineq]*y[ineq]))));ys=c['full_scaled_active_dual'];yb=c['basis_dual'];z=c['scaled_solution'];ab=(sparse.diags(E[active[basis]])@A[active[basis]]@sparse.diags(D)).tocsr();allact=(sparse.diags(E[active])@A[active]@sparse.diags(D)).tocsr();rowerr=float(np.max(abs(allact.toarray()-T@ab.toarray())));rhserr=float(np.max(abs((E[active]*lo[active]-T@(E[active[basis]]*lo[active[basis]]))/E[active])));recovery=float(np.max(abs(T.T@ys-yb)));scaledstat=D*(P@x+q)+ab.T@yb;basisgap=ab@z[:len(D)]-E[active[basis]]*lo[active[basis]];saddleres=float(max(np.max(abs(scaledstat)),np.max(abs(basisgap))));wrong=P@x+q-A.T@y;wrongdef=float(np.max(abs(wrong-g)));wrongdrop=P@x+q # Removing actual support forces must be detected.
 checks=dict(all_original_rows=A.shape[0]==2208,all_original_DOF=P.shape[0]==72230,positive_scale=bool(np.all(D>0)&np.all(E>0)),exact_P_symmetry=(P-P.T).nnz==0,all_active_rows_reconstructed=rowerr<1e-10,all_active_RHS_reconstructed=rhserr<1e-10,full_physical_conic_rows_retained=len(y)==A.shape[0],slack_archive=float(np.max(abs(sl-c['physical_slack_mm'])))<1e-12,stationarity_archive=float(np.max(abs(g-c['physical_stationarity_N'])))<1e-10,producer_metrics=max(abs(metrics[k]-s[k]) for k in metrics)<1e-10,conic_recovery_reproduced=abs(recovery-s['conic_recovery_max_basis_residual'])<1e-10,scaled_saddle_residual_reproduced=abs(saddleres-s['max_scaled_saddle_residual'])<1e-9,wrong_dual_sign_rejected=wrongdef>1e-3,missing_support_rejected=float(np.max(abs(wrongdrop-g)))>1e-3)
 qualified=all(v<1e-8 for v in metrics.values());checks['qualification_matches']=qualified==s['physical_KKT_qualified'];result=dict(status='ACTUAL_P1_MATRIXFREE_INDEPENDENT_AUDIT_PASS' if all(checks.values()) else 'ACTUAL_P1_MATRIXFREE_INDEPENDENT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),producer=ref(out/'producer.py'),checks={k:bool(v) for k,v in checks.items()},metrics=metrics,maximum_scaled_row_error=rowerr,maximum_physical_RHS_error_mm=rhserr,conic_basis_residual=recovery,scaled_saddle_residual=saddleres,wrong_dual_sign_defect_N=wrongdef,all2169contact_rows_checked=True,all14branches_checked=True,physical_KKT_qualified=qualified,actual_support_updates=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-start,limitations=['Independent assembly-unit/algebra/cone audit only. Producer matrix origin must separately agree with original product FE reconstruction.','Audit PASS confirms measured rejection when physical KKT fails; it never qualifies an equilibrium, stress, mesh, whole-system gate or release.']);dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if all(checks.values()) else 2)
if __name__=='__main__':main()
